const items = $input.all();

for (let item of items) {
  const aiResponseText = item.json.text; // Output teks dari LLM

  try {
    // 1. Bersihkan formatting jika AI memberikan markdown ```json ... ```
    const cleanJson = aiResponseText.replace(/```json|```/g, '').trim();

    // 2. Parse string menjadi Objek
    let parsedData = JSON.parse(cleanJson);

    // FISIKAN HANDLING: Jika AI membungkus objek dalam array `candidates`
    if (parsedData.candidates && Array.isArray(parsedData.candidates) && parsedData.candidates.length > 0) {
      parsedData = parsedData.candidates[0];
    } else if (Array.isArray(parsedData) && parsedData.length > 0) {
      parsedData = parsedData[0];
    }

    // 3. Masukkan ke item.json agar bisa dipanggil node selanjutnya
    item.json.ai_name = parsedData.candidate_name || "Tidak Terdeteksi";
    item.json.ai_exp = parsedData.years_of_experience || 0;

    // Handling array skills
    if (Array.isArray(parsedData.top_skills)) {
      item.json.ai_skills = parsedData.top_skills.join(", ");
    } else {
      item.json.ai_skills = parsedData.top_skills || "-";
    }

    item.json.ai_summary = parsedData.summary || "-";
    item.json.ai_score = parsedData.score || 0;
    item.json.ai_rec = parsedData.hiring_recommendation || "-";

  } catch (error) {
    // Fallback jika AI gagal generate JSON valid
    item.json.error = "Gagal parsing JSON dari AI: " + error.message;
    item.json.raw_output = aiResponseText;
  }
}

return items;

const items = $input.all(); // Ambil data input 

for (let item of items) {
  const binaryData = item.binary?.Upload_CV__PDF_;

  if (binaryData) {
    item.json.cv_base64 = binaryData.data; // Data base64 internal 
    item.json.fileName = binaryData.fileName;
  }

  // Tambahkan tanggal format Indonesia menggunakan Luxon 
  item.json.tanggal_input = DateTime.now().toFormat('dd-MM-yyyy HH:mm');
}

return items;
